// Extract headlines safely from both RSS feeds
const redditRaw = $('Reddit Crypto RSS').first()?.json?.data || '';
const coindeskRaw = $('CoinDesk RSS').first()?.json?.data || '';

function extractTitles(xml) {
  if (typeof xml !== 'string') return [];
  const titles = [];
  const re = /<title[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/gi;
  let m;
  while ((m = re.exec(xml)) !== null) {
    const t = m[1].replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#39;/g,"'").replace(/&quot;/g,'"').trim();
    if (t && !t.includes('CryptoCurrency') && !t.includes('CoinDesk') && t.length > 10) {
      titles.push(t);
    }
  }
  return titles.slice(0, 15);
}

const redditHeadlines = extractTitles(redditRaw);
const coindeskHeadlines = extractTitles(coindeskRaw);

return [{
  json: {
    redditHeadlines: redditHeadlines,
    coindeskHeadlines: coindeskHeadlines,
    timestamp: new Date().toISOString()
  }
}];

