const resp = $('Gemini Consensus Check').first()?.json;
let parsed;
try {
  const text = resp?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  parsed = JSON.parse(text);
} catch(e) {
  parsed = { consensus: false, events: [] };
}

if (!parsed || !parsed.consensus || !parsed.events || parsed.events.length === 0) {
  // HALT: No consensus found or Gemini transient error; stop this branch gracefully
  return [];
}

return [{
  json: {
    consensus: true,
    events: parsed.events,
    combined_summary: parsed.combined_summary || parsed.events.map(e => e.summary).join('. '),
    timestamp: new Date().toISOString()
  }
}];

const consensusData = $('Parse Consensus (Halt if None)').first()?.json || {};
const ragResults = $('Supabase RAG Vector Search').first()?.json;

let historicalContext = 'No relevant historical context found in RAG memory.';
if (Array.isArray(ragResults) && ragResults.length > 0) {
  historicalContext = ragResults.map((r, i) => `[${i+1}] (similarity: ${(r.similarity * 100).toFixed(1)}%) ${r.content}`).join('\n\n');
} else if (ragResults && ragResults.data && Array.isArray(ragResults.data)) {
  historicalContext = ragResults.data.map((r, i) => `[${i+1}] (similarity: ${(r.similarity * 100).toFixed(1)}%) ${r.content}`).join('\n\n');
}

return [{
  json: {
    breaking_news: consensusData.combined_summary || '',
    events: consensusData.events || [],
    historical_context: historicalContext,
    timestamp: consensusData.timestamp || new Date().toISOString()
  }
}];

const resp = $('Gemini Sentiment Scoring').first()?.json;
let sentiment;
try {
  const text = resp?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  sentiment = JSON.parse(text);
} catch(e) {
  sentiment = { sentiment_score: 0, is_volatile: false };
}

if (!sentiment || !sentiment.is_volatile) {
  // Not volatile enough to alert or transient error; halt branch gracefully
  return [];
}

return [{
  json: {
    sentiment_score: sentiment.sentiment_score,
    sentiment_label: sentiment.sentiment_label,
    confidence: sentiment.confidence,
    analysis: sentiment.analysis,
    alert_message: sentiment.alert_message || `⚡ SENTIMENT ALERT: Score ${sentiment.sentiment_score}/100 (${sentiment.sentiment_label})`,
    is_volatile: true
  }
}];

const sentimentData = $('Parse Sentiment (Halt if Calm)').first().json;
const usersResp = $('Fetch Telegram Users (Alert)').first().json;

let users = [];
if (Array.isArray(usersResp)) {
  users = usersResp;
} else if (Array.isArray(usersResp?.data)) {
  users = usersResp.data;
}

if (users.length === 0) return [];

const score = sentimentData.sentiment_score;
const emoji = score > 60 ? '🟢🚀' : '🔴⚠️';
const msg = `${emoji} *QUANT TERMINAL // SENTIMENT ALERT*\n━━━━━━━━━━━━━━━━━━━━━━━━\n📊 *Score:* \`${score}/100\` (${sentimentData.sentiment_label})\n🎯 *Confidence:* \`${(sentimentData.confidence * 100).toFixed(0)}%\`\n\n${sentimentData.analysis}\n\n⚡ ${sentimentData.alert_message}\n\n🕒 \`${new Date().toISOString().slice(0,19).replace('T',' ')} UTC\``;

return users.map(u => ({
  json: {
    chat_id: u.telegram_chat_id,
    message: msg
  }
}));

// 1. Gather wallet data
const walletsItems = $('Fetch All Paper Wallets').all();
const userMap = {};
for (const item of walletsItems) {
  const w = item.json;
  if (!w || !w.user_id) continue;
  if (!userMap[w.user_id]) userMap[w.user_id] = {};
  userMap[w.user_id][w.asset_symbol] = parseFloat(w.balance) || 0;
}

// 2. Parse Binance targeted tickers
const tickerItems = $('Binance Spot Tickers').all();
const priceMap = { USD: 1.0 };
const symbolMapping = {
  'BTCUSDT': 'BTC',
  'ETHUSDT': 'ETH',
  'SOLUSDT': 'SOL',
  'DOGEUSDT': 'DOGE'
};

for (const item of tickerItems) {
  const t = item.json;
  if (t && symbolMapping[t.symbol]) {
    priceMap[symbolMapping[t.symbol]] = parseFloat(t.price || t.lastPrice) || 0;
  }
}

// Fallback prices
if (!priceMap.BTC) priceMap.BTC = 79900;
if (!priceMap.ETH) priceMap.ETH = 2500;
if (!priceMap.SOL) priceMap.SOL = 104;
if (!priceMap.DOGE) priceMap.DOGE = 0.09;

// 3. Get telegram linked users
const userItems = $('Fetch Telegram Users (Update)').all();
const tgUsers = [];
for (const item of userItems) {
  const u = item.json;
  if (u && u.telegram_chat_id) {
    tgUsers.push(u);
  }
}

if (tgUsers.length === 0) return [];

const messages = [];
for (const u of tgUsers) {
  const balances = userMap[u.id];
  if (!balances) continue;

  let totalUsd = 0;
  const lines = [];

  // USD Cash first
  const usdBal = balances['USD'] || 0;
  totalUsd += usdBal;
  lines.push(`💵 USD Cash: $${usdBal.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2})}`);

  // Other assets
  for (const [sym, bal] of Object.entries(balances)) {
    if (sym === 'USD' || bal <= 0) continue;
    const price = priceMap[sym] || 0;
    const val = bal * price;
    totalUsd += val;
    lines.push(`🪙 ${sym}: ${Number(bal).toFixed(4)} (~$${val.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2})})`);
  }

  const pnl = totalUsd - 100000;
  const pnlSign = pnl >= 0 ? '+' : '';
  const pnlEmoji = pnl >= 0 ? '📈' : '📉';

  const msg = `⏱️ *15-MIN PORTFOLIO UPDATE*\n━━━━━━━━━━━━━━━━━━━━━━━━\n${lines.join('\n')}\n━━━━━━━━━━━━━━━━━━━━━━━━\n💼 *Total Value:* \`$${totalUsd.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2})}\`\n${pnlEmoji} *PnL:* \`${pnlSign}$${pnl.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2})}\`\n🕒 \`${new Date().toISOString().slice(0,19).replace('T',' ')} UTC\``;

  messages.push({ json: { chat_id: u.telegram_chat_id, message: msg } });
}

return messages;
